-- ----------------------------
-- Table structure for academic_record
-- ----------------------------
DROP TABLE IF EXISTS `academic_record`;
CREATE TABLE `academic_record`  (
  `student_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '学号',
  `subject_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '科目名称',
  `score` decimal(5, 2) NOT NULL COMMENT '成绩',
  `credit` decimal(3, 1) DEFAULT NULL COMMENT '学分',
  `academic_year` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '学年',
  `semester` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '学期',
  `created_at` timestamp(0) DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp(0) DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`student_number`, `subject_name`, `academic_year`, `semester`) USING BTREE,
  CONSTRAINT `fk_academic_record_seeker` FOREIGN KEY (`student_number`) REFERENCES `job_seeker` (`student_number`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

