-- ----------------------------
-- Table structure for application
-- ----------------------------
DROP TABLE IF EXISTS `application`;
CREATE TABLE `application`  (
  `id` int(0) NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `job_id` int(0) NOT NULL COMMENT '职位ID',
  `student_phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '求职者电话',
  `job_intention` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '求职意向',
  `expected_salary` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '期望薪资',
  `resume_file` longblob COMMENT '简历文件(存储PDF/DOC等格式)',
  `status` enum('已投递','已通过','已拒绝') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '已投递' COMMENT '申请状态',
  `application_time` timestamp(0) DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `review_time` timestamp(0) DEFAULT NULL COMMENT '审核时间',
  `review_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '审核备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_job_student`(`job_id`, `student_phone`) USING BTREE,
  INDEX `student_phone`(`student_phone`) USING BTREE,
  CONSTRAINT `application_ibfk_1` FOREIGN KEY (`job_id`) REFERENCES `job_position` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `application_ibfk_2` FOREIGN KEY (`student_phone`) REFERENCES `job_seeker` (`phone`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 47 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of application
-- ----------------------------

-- ----------------------------
-- Table structure for job_position
-- ----------------------------
DROP TABLE IF EXISTS `job_position`;
CREATE TABLE `job_position`  (
  `id` int(0) NOT NULL AUTO_INCREMENT COMMENT '自增编号',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '岗位名称',
  `salary` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '薪资详情',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '职位详情',
  `benefits` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '员工福利',
  `contact_phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '联系人电话(招聘者电话)',
  `work_location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '工作地点',
  `education_requirement` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '学历要求',
  `experience_requirement` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '经验要求',
  `status` enum('待审核','审核不通过','正在招聘','已关闭') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '待审核',
  `created_at` timestamp(0) DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp(0) DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `contact_phone`(`contact_phone`) USING BTREE,
  CONSTRAINT `job_position_ibfk_1` FOREIGN KEY (`contact_phone`) REFERENCES `recruiter` (`phone`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 65 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

